import { challengeReward } from './catalog.ts';
import { MAX_BONUS_STARS_PER_ROUND } from './constants.ts';
import { isInWeek } from './time.ts';
import type { Catalog, ChildChallenge, FamilyState, StarEntry } from './types.ts';

/** Positive "earned" entries: completions and spark bonuses (spec 14.1: adjust does not count). */
export function isEarned(entry: StarEntry): boolean {
  return entry.delta > 0 && (entry.reason === 'completion' || entry.reason === 'spark_bonus');
}

export function entriesFor(state: FamilyState, childId: string): StarEntry[] {
  return state.ledger.filter((e) => e.childId === childId);
}

/** Stars to spend in the reward shop (all deltas). */
export function spendableStars(state: FamilyState, childId: string): number {
  return entriesFor(state, childId).reduce((sum, e) => sum + e.delta, 0);
}

/** Lifetime stars: used for milestones, competitions and family goals. Never decreases. */
export function totalStars(state: FamilyState, childId: string): number {
  return entriesFor(state, childId).reduce((sum, e) => (isEarned(e) ? sum + e.delta : sum), 0);
}

/** Stars a child has asked to spend but a parent has not confirmed yet. */
export function reservedStars(state: FamilyState, childId: string): number {
  return state.rewardRequests
    .filter((r) => r.childId === childId && r.status === 'requested')
    .reduce((sum, r) => sum + r.costStars, 0);
}

export function availableStars(state: FamilyState, childId: string): number {
  return spendableStars(state, childId) - reservedStars(state, childId);
}

export function weekStars(state: FamilyState, childId: string, weekStart: string): number {
  const tz = state.family.settings.timeZone;
  return entriesFor(state, childId).reduce(
    (sum, e) => (isEarned(e) && isInWeek(e.createdAt, weekStart, tz) ? sum + e.delta : sum),
    0,
  );
}

export function earnedSince(state: FamilyState, childId: string, sinceIso: string): number {
  const since = new Date(sinceIso).getTime();
  return entriesFor(state, childId).reduce(
    (sum, e) => (isEarned(e) && new Date(e.createdAt).getTime() >= since ? sum + e.delta : sum),
    0,
  );
}

/**
 * Bonus stars a challenge has given since its latest approval. The ledger is in
 * the order the engine wrote it, so this does not depend on device clocks.
 */
export function bonusStarsThisRound(state: FamilyState, challenge: ChildChallenge): number {
  const completionIds = new Set(state.completions.filter((c) => c.childChallengeId === challenge.id).map((c) => c.id));
  let count = 0;
  for (const entry of state.ledger) {
    if (entry.reason === 'completion' && entry.refId !== null && completionIds.has(entry.refId)) count = 0;
    else if (entry.reason === 'spark_bonus' && entry.refId === challenge.id) count += 1;
  }
  return count;
}

/** Whether the next full egg gives a bonus star. Praise-card challenges never give stars. */
export function canEarnBonusStar(state: FamilyState, catalog: Catalog, challenge: ChildChallenge): boolean {
  return (
    state.family.settings.sparkBonusEnabled &&
    challengeReward(catalog, challenge) === 'star' &&
    bonusStarsThisRound(state, challenge) < MAX_BONUS_STARS_PER_ROUND
  );
}
